import{_ as i,a0 as p,w as o,s as d,ao as t,I as r,x as s,a1 as n,A as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"在 Apache Cassandra 中定義和優化數據分區 | LCTT x X-CMD","titleTemplate":false,"description":"在 Apache Cassandra 中定義和優化數據分區 | LCTT (202110) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Apache Cassandra 中定義和優化數據分區 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Apache Cassandra 中定義和優化數據分區 | LCTT (202110) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202110/20200504 Define and optimize data partitions in Apache Cassandra","title":"在 Apache Cassandra 中定義和優化數據分區","tag":"202110","desc":""},"relativePath":"202110/20200504 Define and optimize data partitions in Apache Cassandra.md","filePath":"[post].md"}'),h={name:"202110/20200504 Define and optimize data partitions in Apache Cassandra.md"};function g(u,a,C,c,b,m){const e=p("Link");return o(),d("div",null,[a[25]||(a[25]=t(`<h1 id="在-apache-cassandra-中定義和優化數據分區" tabindex="-1">在 Apache Cassandra 中定義和優化數據分區 <a class="header-anchor" href="#在-apache-cassandra-中定義和優化數據分區" aria-label="Permalink to “在 Apache Cassandra 中定義和優化數據分區”">​</a></h1><blockquote><p>速度和可擴展性是 Apache Cassandra 不變的追求；來學習一下如何充分發揮它的專長吧。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202110/22/103651gse3iyiajyaagk34.jpg" alt=""></p><p>Apache Cassandra 是一個數據庫，但又不是一個簡單的資料庫；它是一個複製資料庫，專為可擴展性、高可用性、低延遲和良好性能而設計調整。Cassandra 可以幫你的數據在區域性中斷、硬件故障時，以及很多管理員認為數據量過多的情況下倖免於難。</p><p>全面掌握數據分區知識，你就能讓 Cassandra 集羣實現良好的設計、極高的性能和可擴展性。在本文中，我將探究如何定義分區，Cassandra 如何使用這些分區，以及一些你應該瞭解的最佳實踐方案和已知問題。</p><p>基本概念是這樣的: 供資料庫關鍵函數（如數據分發、複製和索引化）使用的原子單元，單個這樣的數據塊就是一個分區。分佈式數據系統通常會把傳入的數據分配到這些分區中，使用簡單的數學函數（例如 identity 或 hashing 函數）執行分區過程，並用得到的 “分區鍵” 對數據分組，進一步再形成分區。例如，假設傳入數據是服務器日誌，使用 “identity” 分區函數和每個日誌的時間戳（四捨五入到小時值）作為分區鍵，我們可以對這些數據進行分區，實現每個分區各保存一小時的日誌的目的。</p><h3 id="cassandra-中的數據分區" tabindex="-1">Cassandra 中的數據分區 <a class="header-anchor" href="#cassandra-中的數據分區" aria-label="Permalink to “Cassandra 中的數據分區”">​</a></h3><p>Cassandra 作為分佈式系統運行，並且符合前述數據分區原則。使用 Cassandra，數據分區依賴於在集羣級別配置的算法和在表級別配置的分區鍵。</p><p><img src="https://opensource.com/sites/default/files/uploads/apache_cassandra_1_0.png" alt="Cassandra data partition" title="Cassandra data partition"></p><p>Cassandra 查詢語言（CQL）使用大家很熟悉的 SQL 表、行、列等術語。在上面的示例圖中，表配置的主鍵中包含了分區鍵，具體格式為：<ruby>主鍵<rt>Primary Key</rt></ruby> = <ruby>分區鍵<rt>Partition Key</rt></ruby> + [<ruby>聚簇列<rt>Clustering Columns</rt></ruby>] 。</p><p>Cassandra 中的主鍵既定義了唯一的數據分區，也包含着分區內的數據排列依據信息。數據排列信息取決於聚簇列（非必需項）。每個唯一的分區鍵代表着服務器（包括其副本所在的服務器）中管理的若干行。</p><h3 id="在-cql-中定義主鍵" tabindex="-1">在 CQL 中定義主鍵 <a class="header-anchor" href="#在-cql-中定義主鍵" aria-label="Permalink to “在 CQL 中定義主鍵”">​</a></h3><p>接下來的四個示例演示瞭如何使用 CQL 語法表示主鍵。定義主鍵會讓數據行分到不同的集合裏，通常這些集合就是分區。</p><h4 id="定義方式-1-分區鍵-log-hour-聚簇列-無" tabindex="-1">定義方式 1（分區鍵：log_hour，聚簇列：無） <a class="header-anchor" href="#定義方式-1-分區鍵-log-hour-聚簇列-無" aria-label="Permalink to “定義方式 1（分區鍵：log_hour，聚簇列：無）”">​</a></h4><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>CREATE TABLE server_logs(</span></span>
<span class="line"><span>   log_hour TIMESTAMP PRIMARYKEY,</span></span>
<span class="line"><span>   log_level text,</span></span>
<span class="line"><span>   message text,</span></span>
<span class="line"><span>   server text</span></span>
<span class="line"><span>   )</span></span></code></pre></div><p>這裏，有相同 <code>log_hour</code> 的所有行都會進入同一個分區。</p><h4 id="定義方式-2-分區鍵-log-hour-聚簇列-log-level" tabindex="-1">定義方式 2（分區鍵：log_hour，聚簇列：log_level） <a class="header-anchor" href="#定義方式-2-分區鍵-log-hour-聚簇列-log-level" aria-label="Permalink to “定義方式 2（分區鍵：log_hour，聚簇列：log_level）”">​</a></h4><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>CREATE TABLE server_logs(</span></span>
<span class="line"><span>   log_hour TIMESTAMP,</span></span>
<span class="line"><span>   log_level text,</span></span>
<span class="line"><span>   message text,</span></span>
<span class="line"><span>   server text,</span></span>
<span class="line"><span>   PRIMARY KEY (log_hour, log_level)</span></span>
<span class="line"><span>   )</span></span></code></pre></div><p>此定義方式與方式 1 使用了相同的分區鍵，但此方式中，每個分區的所有行都會按 <code>log_level</code> 升序排列。</p><h4 id="定義方式-3-分區鍵-log-hour-server-聚簇列-無" tabindex="-1">定義方式 3（分區鍵：log_hour，server，聚簇列：無） <a class="header-anchor" href="#定義方式-3-分區鍵-log-hour-server-聚簇列-無" aria-label="Permalink to “定義方式 3（分區鍵：log_hour，server，聚簇列：無）”">​</a></h4><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>CREATE TABLE server_logs(</span></span>
<span class="line"><span>   log_hour TIMESTAMP,</span></span>
<span class="line"><span>   log_level text,</span></span>
<span class="line"><span>   message text,</span></span>
<span class="line"><span>   server text,</span></span>
<span class="line"><span>   PRIMARY KEY ((log_hour, server))</span></span>
<span class="line"><span>   )</span></span></code></pre></div><p>在此定義中，<code>server</code> 和 <code>log_hour</code> 字段都相同的行才會進入同一個分區。</p><h4 id="定義方式-4-分區鍵-log-hour-server-聚簇列-log-level" tabindex="-1">定義方式 4（分區鍵：log_hour，server，聚簇列：log_level） <a class="header-anchor" href="#定義方式-4-分區鍵-log-hour-server-聚簇列-log-level" aria-label="Permalink to “定義方式 4（分區鍵：log_hour，server，聚簇列：log_level）”">​</a></h4><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>CREATE TABLE server_logs(</span></span>
<span class="line"><span>   log_hour TIMESTAMP,</span></span>
<span class="line"><span>   log_level text,</span></span>
<span class="line"><span>   message text,</span></span>
<span class="line"><span>   server text,</span></span>
<span class="line"><span>   PRIMARY KEY ((log_hour, server),log_level)</span></span>
<span class="line"><span>   )WITH CLUSTERING ORDER BY (column3 DESC);</span></span></code></pre></div><p>此定義方式與方式 3 分區相同，但分區內的行會依照 <code>log_level</code> 降序排列。</p><h3 id="cassandra-如何使用分區鍵" tabindex="-1">Cassandra 如何使用分區鍵 <a class="header-anchor" href="#cassandra-如何使用分區鍵" aria-label="Permalink to “Cassandra 如何使用分區鍵”">​</a></h3><p>Cassandra 依靠分區鍵來確定在哪個節點上存儲數據，以及在需要時定位數據。Cassandra 通過查看錶中的分區鍵來執行這些讀取和寫入操作，並使用<ruby>令牌<rt>tokens</rt></ruby>（一個 $-2^{63}$ 到 $+2^{63}-1$ 範圍內的 long 類型值）來進行數據分佈和索引。這些令牌通過分區器映射到分區鍵，分區器使用了將分區鍵轉換為令牌的分區函數。通過這種令牌機制，Cassandra 集羣的每個節點都擁有一組數據分區。然後分區鍵在每個節點上啓用數據索引。</p><p><img src="https://opensource.com/sites/default/files/uploads/apache_cassandra_2_0.png" alt="Cassandra cluster with 3 nodes and token-based ownership" title="Cassandra cluster with 3 nodes and token-based ownership"></p>`,28)),r("p",null,[a[1]||(a[1]=s("圖中顯示了一個三節點的 Cassandra 集羣以及相應的令牌範圍分配。這只是一個簡單的示意圖：具體實現過程使用了 ",-1)),n(e,{href:"https://www.instaclustr.com/cassandra-vnodes-how-many-should-i-use/"},{default:l(()=>[...a[0]||(a[0]=[s("Vnodes",-1)])]),_:1}),a[2]||(a[2]=s("。",-1))]),a[26]||(a[26]=t('<h3 id="數據分區對-cassandra-集羣的影響" tabindex="-1">數據分區對 Cassandra 集羣的影響 <a class="header-anchor" href="#數據分區對-cassandra-集羣的影響" aria-label="Permalink to “數據分區對 Cassandra 集羣的影響”">​</a></h3><p>用心的分區鍵設計對於實現用例的理想分區大小至關重要。合理的分區可以實現均勻的數據分佈和強大的 I/O 性能。分區大小對 Cassandra 集羣有若干需要注意的影響：</p><ul><li>讀取性能 —— 為了在磁盤上的 SSTables 文件中找到分區，Cassandra 使用緩存、索引和索引摘要等數據結構。過大的分區會降低這些數據結構的維護效率，從而對性能產生負面影響。Cassandra 新版本在這方面取得了長足的進步：特別是 3.6 及其以上版本的 Cassandra 引擎引入了存儲改進，針對大型分區，可以提供更好的性能，以及更強的應對內存問題和崩潰的彈性。</li><li>內存使用 —— 大分區會對 JVM 堆產生更大的壓力，同時分區的增大也降低了垃圾收集機制的效率。</li><li>Cassandra 修復 —— 大分區使 Cassandra 執行修復維護操作（通過跨副本比較數據來保持數據一致）時更加困難。</li><li>“墓碑”刪除 —— 聽起來可能有點駭人，Cassandra 使用稱為“<ruby>墓碑<rt>tombstones</rt></ruby>”的獨特標記來記錄要刪除的數據。如果沒有合適的數據刪除模式和壓縮策略，大分區會使刪除過程變得更加困難。</li></ul>',3)),r("p",null,[a[4]||(a[4]=s("雖然這些影響可能會讓人更傾向於簡單地設計能產生小分區的分區鍵，但數據訪問模式對理想的分區大小也有很大影響（有關更多信息，請閲讀關於 ",-1)),n(e,{href:"https://www.instaclustr.com/resource/6-step-guide-to-apache-cassandra-data-modelling-white-paper/"},{default:l(()=>[...a[3]||(a[3]=[s("Cassandra 數據建模",-1)])]),_:1}),a[5]||(a[5]=s(" 的深入講解）。數據訪問模式可以定義為表的查詢方式，包括表的所有 ",-1)),a[6]||(a[6]=r("code",null,"select",-1)),a[7]||(a[7]=s(" 查詢。 理想情況下，CQL 選擇查詢應該在 ",-1)),a[8]||(a[8]=r("code",null,"where",-1)),a[9]||(a[9]=s(" 子句中只使用一個分區鍵。也就是説，當查詢可以從單個分區，而不是許多較小的分區獲取所需數據時，Cassandra 是最有效率的。",-1))]),a[27]||(a[27]=t('<h3 id="分區鍵設計的最佳實踐" tabindex="-1">分區鍵設計的最佳實踐 <a class="header-anchor" href="#分區鍵設計的最佳實踐" aria-label="Permalink to “分區鍵設計的最佳實踐”">​</a></h3><p>遵循分區鍵設計的最佳實踐原則，這會幫你得到理想的分區大小。根據經驗，Cassandra 中的最大分區應保持在 100MB 以下。理想情況下，它應該小於 10MB。雖然 Cassandra 3.6 及其以上版本能更好地支持大分區，但也必須對每個工作負載進行仔細的測試和基準測試，以確保分區鍵設計能夠支持所需的集羣性能。</p><p>具體來説，這些最佳實踐原則適用於任何分區鍵設計：</p><ul><li>分區鍵的目標必須是將理想數量的數據放入每個分區，以支持其訪問模式的需求。</li><li>分區鍵應禁止無界分區：那些大小可能隨着時間無限增長的分區。例如，在上面的 <code>server_logs</code> 示例中，隨着服務器日誌數量的不斷增加，使用服務器列作為分區鍵就會產生無界分區。相比之下，使用 <code>log_hour</code> 將每個分區限制為一個小時數據的方案會更好。</li><li>分區鍵還應避免產生分區傾斜，即分區增長不均勻，有些分區可能隨着時間的推移而不受限制地增長。在 <code>server_logs</code> 示例中，在一台服務器生成的日誌遠多於其他服務器的情況下使用服務器列會產生分區傾斜。為了避免這種情況，可以從表中引入另一個屬性來強制均勻分佈，即使要創建一個虛擬列來這樣做，也是值得的。</li><li>使用時間元素和其他屬性的組合分區鍵，這對時間序列數據分區很有幫助。這種方式可以防止無界分區，使訪問模式能夠在查詢特定數據時使用時間屬性，而且能夠對特定時間段內的數據進行刪除。上面的每個示例都使用了 <code>log_hour</code> 時間屬性來演示這一點。</li></ul><p>還有一些工具可用於幫助測試、分析和監控 Cassandra 分區，以檢查所選模式是否高效。通過仔細設計分區鍵，使解決方案的數據和需求保持一致，並遵循最佳實踐原則來優化分區大小，你就可以充分利用數據分區，更好地發揮 Cassandra 的可擴展性和性能潛力。</p><hr>',6)),r("p",null,[a[11]||(a[11]=s("via: ",-1)),n(e,{href:"https://opensource.com/article/20/5/apache-cassandra"},{default:l(()=>[...a[10]||(a[10]=[s("https://opensource.com/article/20/5/apache-cassandra",-1)])]),_:1})]),r("p",null,[a[16]||(a[16]=s("作者：",-1)),n(e,{href:"https://opensource.com/users/anil-inamdar"},{default:l(()=>[...a[12]||(a[12]=[s("Anil Inamdar",-1)])]),_:1}),a[17]||(a[17]=s(" 選題：",-1)),n(e,{href:"https://github.com/lujun9972"},{default:l(()=>[...a[13]||(a[13]=[s("lujun9972",-1)])]),_:1}),a[18]||(a[18]=s(" 譯者：",-1)),n(e,{href:"https://github.com/unigeorge"},{default:l(()=>[...a[14]||(a[14]=[s("unigeorge",-1)])]),_:1}),a[19]||(a[19]=s(" 校對：",-1)),n(e,{href:"https://github.com/wxy"},{default:l(()=>[...a[15]||(a[15]=[s("wxy",-1)])]),_:1})]),r("p",null,[a[22]||(a[22]=s("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...a[20]||(a[20]=[s("LCTT",-1)])]),_:1}),a[23]||(a[23]=s(" 原創編譯，",-1)),n(e,{href:"https://linux.cn/"},{default:l(()=>[...a[21]||(a[21]=[s("Linux中國",-1)])]),_:1}),a[24]||(a[24]=s(" 榮譽推出",-1))])])}const _=i(h,[["render",g]]);export{T as __pageData,_ as default};
